insert into services (id, name, kind, duration_min, price, is_trial, first_time_only, return_days, image, description, sort, active) values
  ('cook_trial', 'はじめての料理教室（体験）', 'class', 120, 2500, true, true, 10, 'cook_trial.png', '初めての方限定の体験レッスン。季節の一品を、ひと通り自分の手で作って食べて帰ります。', 1, true),
  ('cook_washoku', '基本の和食', 'class', 150, 5500, false, false, 14, 'cook_washoku.png', 'だしのとり方から、煮物・焼き物・汁物まで。毎月メニューが変わります。', 2, true),
  ('cook_western', '定番の洋食', 'class', 150, 5800, false, false, 14, 'cook_western.png', 'ハンバーグやグラタンなど、家で作れる洋食を手順から。', 3, true),
  ('cook_italian', '手打ちパスタ', 'class', 120, 5200, false, false, 14, 'cook_italian.png', '生地をこねて延ばして切るところから。ソースも2種類作ります。', 4, true),
  ('cook_bread', '手ごねパン', 'class', 180, 6200, false, false, 14, 'cook_bread.png', 'こねから焼き上がりまで。焼きたてを食べて、残りはお持ち帰り。', 5, true),
  ('cook_sweets', '季節のお菓子', 'class', 150, 5600, false, false, 14, 'cook_sweets.png', 'タルトやシフォンなど、季節の素材のお菓子。ラッピングも練習します。', 6, true),
  ('cook_ferment', '発酵ごはん（味噌・ぬか漬け）', 'class', 120, 4800, false, false, 14, 'cook_ferment.png', '味噌づくりやぬか床の育て方。仕込んだものはお持ち帰り。', 7, true);
